use verus::prelude::*;
use verus::pervasive::seq::Seq;

// A pure spec‐function that counts equal adjacent pairs in a Seq<char>.
// We prove termination by decreasing on s.len().
#[verifier::spec]
#[verifier::decreases(s.len())]
fn count_adj_pairs(s: Seq<char>) -> i8 {
    if s.len() < 2 {
        0
    } else {
        let tail = s.slice(1, s.len());
        if s.index(0) == s.index(1) {
            1 + count_adj_pairs(tail)
        } else {
            count_adj_pairs(tail)
        }
    }
}

#[requires(n >= 0)]
#[requires(s.len() == n as usize)]
#[ensures(result == count_adj_pairs(s.view()))]
fn solve(n: i8, s: Vec<char>) -> i8 {
    // If n < 2, there are no adjacent pairs.
    if n < 2 {
        return 0;
    }

    let mut count: i8 = 0;
    let len = n as usize;
    // We know len >= 2, so len-1 is safe
    for i in 0..(len - 1) {
        if s[i] == s[i + 1] {
            count += 1;
        }
    }
    count
}

